import{_ as o,o as t,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — Sign Out","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-8-sign-out/plan.md","filePath":"feature/authentication/3-2-8-sign-out/plan.md"}'),n={name:"feature/authentication/3-2-8-sign-out/plan.md"};function r(d,e,c,l,h,s){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-sign-out" tabindex="-1">Plan — Sign Out <a class="header-anchor" href="#plan-—-sign-out" aria-label="Permalink to &quot;Plan — Sign Out&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — Logout + gợi ý phương thức đăng nhập lần trước.</p><h2 id="quyet-đinh-lastusedloginmethod-spec-đe-mo" tabindex="-1">Quyết định lastUsedLoginMethod (spec để mở) <a class="header-anchor" href="#quyet-đinh-lastusedloginmethod-spec-đe-mo" aria-label="Permalink to &quot;Quyết định lastUsedLoginMethod (spec để mở)&quot;">​</a></h2><p>Chốt: <strong>FE local storage</strong> (xác nhận với Trung). Không cần thay đổi backend — FE tự lưu method (<code>email</code> | <code>google_oauth</code>) khi login/logout thành công, tự đọc khi render <code>/login</code> để highlight nút.</p><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><strong>[MỚI 2026-09-25]</strong> FE (<code>authService.ts</code>) giờ đã có <code>logout()</code> gọi endpoint này — trước đây <code>Navbar.handleLogout</code> chỉ <code>clearAuth()</code> local, không gọi API. Giờ gọi fire-and-forget (<code>.catch(() =&gt; {})</code>), không chờ response, vẫn <code>clearAuth()</code> + redirect ngay.</li><li><code>POST /api/v1/auth/logout</code> (Bearer + refresh cookie) → blacklist access token (Redis <code>jwt:blacklist:{jti}</code>) + revoke refresh token → clear cookie → ghi audit log → 200.</li><li><strong>Idempotent</strong>: token đã hết hạn/không hợp lệ → vẫn 200 (không báo lỗi).</li><li>Chỉ revoke refresh token của thiết bị hiện tại (không ảnh hưởng thiết bị khác).</li><li><strong>Audit log (2026-09-23):</strong> <code>AuditLog</code> thêm 2 field <code>ipAddress</code> (<code>ip_address</code> VARCHAR 45) + <code>userAgent</code> (<code>user_agent</code> VARCHAR 512). Controller lấy từ header <code>X-Forwarded-For</code> / <code>User-Agent</code>, truyền xuống <code>authService.logout(accessToken, refreshToken, ipAddress, userAgent)</code> và <strong>lưu vào bản ghi audit</strong> (trước đây nhận param nhưng không lưu).</li></ul><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><ol><li>Auth header (Bearer) → access token (thiếu/sai prefix → 401 <code>INVALID_CREDENTIALS</code>).</li><li>Parse token lấy <code>userId</code>; blacklist access + revoke refresh (jti).</li><li><code>INSERT audit_logs (userId, LOGOUT, USER, ipAddress, userAgent)</code> — chỉ khi có <code>userId</code>.</li><li>Clear <code>refreshToken</code> cookie (maxAge=0).</li><li>200 (kể cả token đã hết hạn).</li></ol><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><ul><li>Redis <code>jwt:blacklist:{jti}</code>.</li><li><code>audit_logs</code> thêm cột <code>ip_address</code> (VARCHAR 45), <code>user_agent</code> (VARCHAR 512) — migration <code>brandhub-infrastructure/scripts/migrations/2026-09-23-audit-log-ip-user-agent.sql</code>.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Logout nhiều thiết bị: mỗi thiết bị revoke riêng (đúng spec).</li><li><code>ipAddress</code> lấy từ header <code>X-Forwarded-For</code> — nếu không có reverse proxy set header này đúng, giá trị có thể null/spoof. Chấp nhận ở mức hiện tại (audit nội bộ).</li></ul>',12)])])}const p=o(n,[["render",r]]);export{g as __pageData,p as default};
